head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isurCd = "";          // 발행기관코드 (부모 arr[0])
scwin.isurNm = "";          // 발행기관명 — 종목 기준으로 열면 종목명 (부모 arr[1])
scwin.secugrpId = "";       // 증권그룹ID (부모 arr[2])
scwin.mktId = "";           // 시장구분코드 (부모 arr[3])
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정 (부모 arr[4])
scwin.tpCd = "";            // 관리종목지정업무구분코드 0: 지정 (부모 arr[5])
scwin.isuCd = "";           // 종목코드 (부모 arr[6])
scwin.selTp = "";           // 선택 구분 1: 종목, 2: 발행회사, 3: 전체 (부모 arr[7])
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.isSaved = false;      // 저장·수정에 성공했는지 — 닫을 때 부모에 돌려준다
scwin.DSCL_FORM_CD = "68344";   // 공시안내문 서식코드 (원본 arr[0])
scwin.DSCL_MKT_ID = "1";        // 공시안내문 시장구분 (원본 arr[3])
scwin.RSNCD_ADM_DESIGN = "2";   // 관리종목지정사유 (pcc list_common RSNCD_ADM_DESIGN)
scwin.DEFAULT_GRND_REGUL = "유가증권시장상장규정 제149조의6제1항";    // 신규 근거규정 기본값
scwin.DEFAULT_REMK = "상기 상장지수증권은 다음 반기말까지 관리종목 지정사유를 해소하지 못할 경우 상장 폐지됨을 알려드립니다.\n";   // 신규 기타 기본값 (원본 fn_setRemk)
// 원본 : /etn/ULDSTF08032.gfm (ETN 관리종목지정 팝업)
/*
 * 화면 동작 — (팝업)관리종목지정
 *  - 부모(ULDSTF08031 관리종목지정 목록)가 openPopup 의 data 로 연다. 업무처리번호가 없으면 신규, 있으면 수정이다.
 *  - 신규(종목 기준): 부모가 넘긴 종목을 상세 조회 isuList 에서 찾아 그리드에 둔다. 지정일·지정사유·근거규정을 넣어 저장한다.
 *  - 수정: 업무처리번호로 상세(마스터·종목·지정사유)를 조회해 수정·삭제한다.
 *  - [해제]·[사유변경]: 형제 팝업(ULDSTF08033·08034)을 직접 열지 않고 { next } 로 돌려준다 — 부모가 재조회 뒤 연다(공통 계약서 §3.2).
 *  - 공시안내문작성(ULDSTF92024, 서식 68344). 닫힌 뒤 반환 { isSaved } 또는 X 닫기면 부모가 목록을 다시 조회한다.
 *  - 같은 계열: ULDSTF08032_new(발행회사 기준 신규 지정) · 08033 해제 · 08034 사유변경
 * 업무 분석 : conversion/conversion-front/ui/completed/ULDSTF08032/ULDSTF08032.md (§번호는 이 문서의 절)
 */

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete",    // [삭제]
    guide : "btn_Dscl"          // [안내문작성]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 30
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 30
 * @description 초기화. 버튼을 잠그고 달력 검사를 건 뒤, 부모 파라미터로 신규·수정을 가른다. (원본 gform onload — §3)
 *
 * 부모는 openPopup 의 3번째 인자를 평면으로 넘기므로 $c.data.getParameter() 로 받는다(원본 fn_GetPar arr 0~8 — 계약서 §3.1).
 * 신규는 기본값을 넣고 종목 기준이면 그 종목을 상세 조회 isuList 에서 찾는다. 수정은 상세를 조회한다.
 * 로딩 중에는 버튼을 전부 잠근다 — 조회가 실패해도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
    btn_release.setDisabled(true);
    btn_rsn_change.setDisabled(true);

    // 2) 달력 검사(규칙 37)·서버 현재일
    $c.date.checkCalendarFormat(edt_MktactEnforceDd, "yyyyMMdd");
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 3) 파라미터 수신 — openPopup 의 3번째 인자
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";
    scwin.isurNm = param.isurNm ?? "";
    scwin.secugrpId = param.secugrpId ?? "";
    scwin.mktId = param.mktId ?? "";
    scwin.bzProcsNo = param.bzProcsNo ?? "";
    scwin.tpCd = param.admisuDesignBzTpCd ?? "";
    scwin.isuCd = param.isuCd ?? "";
    scwin.selTp = param.selTp ?? "";

    // 4) 신규 / 수정
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        await scwin.initNewForm();
        return;
    }

    await scwin.applyDetail(scwin.bzProcsNo);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @event
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목선택 클릭. 원본은 ETN 종목 다건 선택 팝업(fn_PopFindEtnCode)을 열어 고른 종목으로 그리드를 바꿨다. (§6.3)
 *
 * 대응하는 팝업이 아직 전환되지 않았다(파일명 불명, pcc 대응 없음) — 공통 계약서 §3.4 대로 버튼은 두고 안내만 한다(§10 #1).
 * 이 화면은 종목 기준(selTp 1)으로 열리면 이 버튼이 잠기므로 보통 쓰이지 않는다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        // TODO: ETN 종목 다건 선택 팝업 전환 뒤 연결 (§10 #1)
        await $c.win.alert("ETN 종목 선택 팝업이 아직 준비되지 않았습니다.\n\n관리종목지정 목록에서 종목을 선택해 신규 등록하세요.");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032.img_SetIsuCd_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_add_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유추가 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_add_onclick = async function (e) {
    try {
        await scwin.openRsnPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032.btn_rsn_add_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_rsn_del_onclick
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유삭제 클릭. 지정사유 그리드에서 고른 행을 지운다. (원본 dts_Rsn.DeleteRow(RowPosition))
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
*/
scwin.btn_rsn_del_onclick = async function (e) {
    try {
        const row = grd_rsn.getFocusedRowIndex();
        if (row < 0) return;

        dlt_rsn.removeRow(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08032.btn_rsn_del_onclick" });
    }
};

