///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectOne
 * @author Inswave
 * @date 2026. 10. 30
 * @description 상세 조회(묶음). 업무처리번호의 마스터·지정사유와 발행기관의 종목내역을 한 번에 받아 본문을 돌려준다. (원본 fn_search·fn_new_onload — §5.1)
 *
 * 원본은 searchEtnAdministrativeIssue 를 DIV_IDX 별(MST·ISU_ITM·RSN_AF)로 세 번 불렀다. 명세는 한 번에 돌려준다.
 * 응답 목록이 여럿이라 target 을 쓰지 않고 본문을 받아 호출하는 쪽이 필요한 것만 담는다(명세 [RESPONSE & 처리] 와 같은 방식).
 * @param {String} bzProcsNo 업무처리번호 (신규 종목 조회는 빈 값)
 * @returns {Promise<Object|null>} 응답 본문 { mst, mstBf, isuList, rsnBfList, rsnAfList } — 실패면 null
 * @hidden N
*/
scwin.selectOne = async function (bzProcsNo) {
    const sbmOptions = {
        id : "sbm_selectOne",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one",
        isProcessMsg : false
    };

    const requestData = {
        bzProcsNo : bzProcsNo,          // 업무처리번호
        orgBzProcsNo : "",              // 원 지정 업무처리번호 (지정 화면은 쓰지 않음)
        isurCd : scwin.isurCd           // 발행기관코드 — 종목내역 조회 기준
    };

    // 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return null;

    return result.responseJSON.body ?? {};
};

/**
 * @method
 * @name scwin.checkDoubleInput
 * @author Inswave
 * @date 2026. 10. 30
 * @description 같은 종목·같은 지정일로 이미 입력된 관리종목 건(자기 건 제외)이 있으면 안내하고 true 를 돌려준다. (원본 fn_check_bz_doubleinput_etn — §5.2)
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 중복 여부
 * @hidden N
*/
scwin.checkDoubleInput = async function (isuCd) {
    dma_chkDbl.setEmptyValue();

    const sbmOptions = {
        id : "sbm_checkDoubleInput",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/check-double-input",
        target : "dma_chkDbl=body",
        isProcessMsg : false
    };

    const requestData = {
        isuCd : isuCd,                                          // 종목코드
        mktactEnforceDd : dma_mst.get("mktactEnforceDd"),      // 지정일
        bzProcsNo : scwin.bzProcsNo                             // 자기 건 제외용 업무처리번호 (신규는 빈 값)
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

    if (!result.responseJSON?.success) return true;     // 확인하지 못하면 저장하지 않는다

    if (dma_chkDbl.get("dupYn") === "Y") {
        await $c.win.alert("[" + dma_chkDbl.get("disclsProcsStatCd") + "]건으로 " + dma_chkDbl.get("disclsProcsDdtm") + "에 이미 입력되어있습니다.");
        return true;
    }

    return false;
};

/**
 * @method
 * @name scwin.checkStatus
 * @author Inswave
 * @date 2026. 10. 30
 * @description 종목의 최신 관리종목 처리건으로 지정을 저장할 수 있는지 판단한다. (원본 fn_getMstStatus_etn — §5.3)
 *
 * 명세는 등록 API 가 같은 확인을 서버에서 한다고 적었지만, 원본처럼 저장 전에 사유를 먼저 안내한다.
 *  - 최신 건의 시행일이 입력한 지정일 이후(같은 날 포함)면 MSG-0020
 *  - 지정은 최신 건이 없거나 해제(4)일 때만 저장할 수 있다 — 아니면 MSG-0021
 * @param {String} isuCd 종목코드
 * @returns {Promise<Boolean>} 저장 가능 여부
 * @hidden N
*/
scwin.checkStatus = async function (isuCd) {
    dma_status.setEmptyValue();

    const sbmOptions = {
        id : "sbm_selectOneStatus",
        method : "get",
        action : "/api/listing/lstproc/etn/adm-isu/select-one-status",
        target : "dma_status=body",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { isuCd : isuCd });

    if (!result.responseJSON?.success) return false;

    const lastTpCd = dma_status.get("admisuDesignBzTpCd");     // 최신 건 업무구분
    const lastDd = dma_status.get("mktactEnforceDd");          // 최신 건 시행일

    if (!$c.util.isEmpty(lastDd) && lastDd >= dma_mst.get("mktactEnforceDd")) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0020", ""));
        return false;
    }

    // 지정은 직전 이력이 없거나 해제여야 한다.
    if (!$c.util.isEmpty(lastTpCd) && lastTpCd !== "4") {
        await $c.win.alert($c.stf.getMessageParam("MSG-0021", ""));
        return false;
    }

    return true;
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 등록(I)·수정(U). 마스터·지정사유를 보내고, 성공하면 업무처리번호를 받아 상세를 다시 조회한다. (원본 fn_save_trs + trs OnSuccess — §5.4)
 *
 * 등록은 업무처리번호를 비워 보내면 서버가 채번한다(명세 mstDto.bzProcsNo) — 원본의 화면 채번(fn_getNewBzProcNo)은 없앴다.
 * 지정사유의 변경후구분(2)·지정해제구분(1)·추가지정여부(N)는 서버가 채운다(원본 fn_save_trs 의 행 루프).
 * 원본의 부모 직접 재조회(fn_parentRefresh)는 반환 규약(isSaved)으로 바꿨다.
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns {Promise<Boolean>} 처리 성공 여부
 * @hidden N
*/
scwin.saveTrs = async function (trJob) {
    dma_saveResult.setEmptyValue();

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : (trJob === "I") ? "/api/listing/lstproc/etn/adm-isu/register-design" : "/api/listing/lstproc/etn/adm-isu/modify-design",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const isuCd = dlt_isu.getCellData(0, "isuCd");

    const requestData = {
        mstDto : {
            bzProcsNo : (trJob === "I") ? "" : scwin.bzProcsNo,       // 등록은 서버 채번
            isuCd : isuCd,                                              // 종목코드 (단건)
            mktactEnforceDd : dma_mst.get("mktactEnforceDd"),          // 지정일
            grndRegulNm : dma_mst.get("grndRegulNm"),                  // 근거규정
            admisuRsnContn : dma_mst.get("admisuRsnContn"),            // 관리종목사유내용
            admisuDesignBzProcsNo : scwin.bzProcsNo,                    // 지정은 서버가 자기 번호로 설정
            remk : dma_mst.get("remk")                                  // 기타
        },
        rsnList : dlt_rsn.getAllJSON().map(row => ({
            admisuDesignRsnCd : row.admisuDesignRsnCd,
            admisuDesignRsnNm : row.admisuDesignRsnNm
        })),
        isuCdList : []                                                  // 비우면 마스터 종목코드 1건
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    const jobNm = (trJob === "I") ? "저장" : "수정";

    if (!result.responseJSON?.success || dma_saveResult.get("result") === "F") {
        // "MSG-A002": "[^] 처리 실패하였습니다." — 서버 메시지가 있으면 함께 보인다.
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm) + ($c.util.isEmpty(dma_saveResult.get("resultMessage")) ? "" : "\n\n" + dma_saveResult.get("resultMessage")));
        return false;
    }

    // "com_complete_0096": "$[0] 되었습니다."
    await $c.win.alert($c.data.getMessage("com_complete_0096", jobNm));
    scwin.isSaved = true;

    if (trJob === "I") scwin.bzProcsNo = dma_saveResult.get("bzProcsNo");

    // 원본처럼 저장 뒤 상세를 다시 읽는다. 번호를 못 받았으면 신규 상태 그대로 둔다.
    if (!$c.util.isEmpty(scwin.bzProcsNo)) await scwin.applyDetail(scwin.bzProcsNo);

    return true;
};

/**
 * @method
 * @name scwin.removeTrs
 * @author Inswave
 * @date 2026. 10. 30
 * @description 관리종목지정 삭제. 업무처리번호만 보낸다. 성공하면 { isSaved : true } 로 팝업을 닫는다. (원본 fn_delete + trs OnSuccess — §5.5)
 *
 * 시장안내공시가 승인된 건은 서버가 삭제를 거부한다(명세) — 원본의 화면 사전 확인(fn_check_delete_discls)은 없앴다.
 * @param
 * @returns
 * @hidden N
*/
scwin.removeTrs = async function () {
    dma_saveResult.setEmptyValue();

    const sbmOptions = {
        id : "sbm_removeTrs",
        method : "post",
        action : "/api/listing/lstproc/etn/adm-isu/remove",
        target : "dma_saveResult=body",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });

    if (!result.responseJSON?.success || dma_saveResult.get("result") === "F") {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제") + ($c.util.isEmpty(dma_saveResult.get("resultMessage")) ? "" : "\n\n" + dma_saveResult.get("resultMessage")));
        return;
    }

    await $c.win.alert($c.data.getMessage("com_complete_0096", "삭제"));
    await $c.win.closePopup({ isSaved : true });
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 진입. 근거규정·기타 기본값을 넣고, 종목이 넘어왔으면 상세 조회 isuList 에서 그 종목을 찾아 그리드에 둔다. (원본 fn_new_onload + dts_Mst OnLoadCompleted — §3)
 *
 * 원본은 종목 기준(gubun 1)일 때 searchEtnCode 로 그 종목 한 행을 받았다. 명세는 발행기관의 종목내역(isuList)을 주므로 종목코드로 거른다.
 * 목록에 없으면 부모가 넘긴 값으로 한 행을 만든다(§10 #2).
 * @param
 * @returns
 * @hidden N
*/
scwin.initNewForm = async function () {
    dma_mst.setEmptyValue();
    dlt_isu.removeAll();
    dlt_rsn.removeAll();

    dma_mst.set("isurCd", scwin.isurCd);
    dma_mst.set("grndRegulNm", scwin.DEFAULT_GRND_REGUL);
    dma_mst.set("remk", scwin.DEFAULT_REMK);

    if (!$c.util.isEmpty(scwin.isuCd)) {
        const body = await scwin.selectOne("");
        const rows = (body?.isuList ?? []).filter(row => row.isuCd === scwin.isuCd);

        if (rows.length === 0) {
            rows.push({ isuCd : scwin.isuCd, isuNm : scwin.isurNm, isurCd : scwin.isurCd });
        }
        dlt_isu.setJSON(rows.map(row => ({ ...row, selected : "F" })));
    }

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.applyDetail
 * @author Inswave
 * @date 2026. 10. 30
 * @description 업무처리번호로 상세를 조회해 마스터·종목·지정사유(변경후)를 화면에 담고 버튼 상태를 맞춘다. (원본 fn_search + dts_* OnLoadCompleted — §5.1)
 *
 * 종목내역은 발행기관 종목 전체에 등록여부(selected)가 붙어 오므로 이 건에 등록된 종목(selected T)만 둔다.
 * 표시가 없으면 마스터의 종목코드 행을 둔다(§10 #3).
 * @param {String} bzProcsNo 업무처리번호
 * @returns
 * @hidden N
*/
scwin.applyDetail = async function (bzProcsNo) {
    const body = await scwin.selectOne(bzProcsNo);
    if (!body) return;

    dma_mst.setJSON(body.mst ?? {});
    scwin.bzProcsNo = dma_mst.get("bzProcsNo") || bzProcsNo;

    const isuList = body.isuList ?? [];
    let rows = isuList.filter(row => row.selected === "T");
    if (rows.length === 0) rows = isuList.filter(row => row.isuCd === dma_mst.get("isuCd"));

    dlt_isu.removeAll();
    dlt_isu.setJSON(rows);

    dlt_rsn.removeAll();
    dlt_rsn.setJSON((body.rsnAfList ?? []).map(row => ({
        bzProcsNo : row.bzProcsNo,
        admisuDesignRsnCd : row.admisuDesignRsnCd,
        admisuDesignRsnNm : row.admisuDesignRsnNm
    })));

    scwin.setFormState();
};

/**
 * @method
 * @name scwin.setFormState
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규·수정에 따라 종목선택·버튼·[해제]·[사유변경] 활성을 정한다. (원본 fn_SetIsuCdBtnShow·fn_SetRelAndChgRsnBtnShow·setButtonSetWithDate·setButtonSetWithDate2 — §6.1)
 *  - 신규: [저장]만, 종목선택은 종목 기준(selTp 1)이 아닐 때만
 *  - 수정: 원본 조합 그대로 — 공시된 건(dscYn Y)이면 지정일이 지났을 때 조회 전용(error), 그 밖에는 [수정]·[삭제]·[안내문작성]
 *  - [해제]·[사유변경]: 신규이거나 미공시(dscYn N)면 잠금
 * @param
 * @returns
 * @hidden N
*/
scwin.setFormState = function () {
    const isNew = $c.util.isEmpty(scwin.bzProcsNo);
    const dscYn = dma_mst.get("dscYn");

    img_SetIsuCd.setDisabled(!isNew || scwin.selTp === "1");

    let status = "insert";
    if (!isNew) {
        const enforceDd = dma_mst.get("mktactEnforceDd");
        const isPassed = !$c.util.isEmpty(enforceDd) && scwin.curDate >= enforceDd;     // 지정일 당일 포함 경과
        status = (dscYn === "Y" && isPassed) ? "error" : "update";
    }
    $c.util.setButtonState("grpBtnBox", status, scwin.BTN_MAP);

    const lockNext = isNew || dscYn === "N";
    btn_release.setDisabled(lockNext);
    btn_rsn_change.setDisabled(lockNext);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 30
 * @description 저장·수정 전 입력값을 검증한다. (원본 fn_CheckForm — §6.2)
 *
 * 순서와 문구는 원본을 따른다: 종목 → 지정일(8자리·익일 이후) → 지정사유 → 근거규정(필수·200byte) → 기타(2000byte) → 업무 중복입력.
 * @param
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
*/
scwin.validate = async function () {
    if (dlt_isu.getRowCount() === 0) {
        await $c.win.alert("[관리지정종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }

    // 지정일 — 원본 checkDdTm("DD", 지정, false): 8자리, 익일 이후
    const enforceDd = dma_mst.get("mktactEnforceDd") ?? "";
    if (enforceDd.length !== 8) {
        await $c.win.alert("[지정일]을 정확히 입력하세요.");
        edt_MktactEnforceDd.focus();
        return false;
    }
    if (scwin.curDate >= enforceDd) {
        await $c.win.alert("[지정일]을 익일 이후로 입력하세요.");
        edt_MktactEnforceDd.focus();
        return false;
    }

    if (dlt_rsn.getRowCount() === 0) {
        await $c.win.alert("[지정사유]를 선택하세요.");
        btn_rsn_add.focus();
        return false;
    }

    if ($c.util.isEmpty(dma_mst.get("grndRegulNm"))) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A005", "근거규정"));
        txb_AdmisuDesignGrndRegulNm.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AdmisuDesignGrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;

    if (await scwin.checkDoubleInput(dlt_isu.getCellData(0, "isuCd"))) return false;

    return true;
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 30
 * @description 신규 저장. 검증 → 종목 최신 상태 확인 → 사용자 확인 → 등록. (원본 fn_save — §6.4)
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;
    if (!await scwin.checkStatus(dlt_isu.getCellData(0, "isuCd"))) return;

    // "[저장] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 30
 * @description 수정. 검증 → 사용자 확인 → 수정. 종목내역·지정사유는 서버가 전체 삭제 후 다시 등록한다. (원본 fn_update — §6.4)
 * @param
 * @returns
 * @hidden N
*/
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 30
 * @description 삭제. 사용자 확인 뒤 삭제한다. (원본 fn_delete — §6.4)
 * @param
 * @returns
 * @hidden N
*/
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" 확인 — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.removeTrs();
};

/**
 * @method
 * @name scwin.openRsnPopup
 * @author Inswave
 * @date 2026. 10. 30
 * @description 사유찾기(관리종목지정사유) 팝업을 열고 고른 사유를 지정사유 그리드에 더한다. 이미 있는 사유면 안내하고 넣지 않는다. (원본 fn_PopFindClssLstRsnCd + fn_SetParRsnCd — §6.5)
 *
 * 원본 fn_GetParRsnCd 의 arr[0] "1"(시장)·arr[1] "07"(사유구분)·arr[5] "N"(기업인수목적회사)을 data 로 넘긴다.
 * 중복 확인은 화면에서 0부터 센다 — pcc isNewValueForDataSet 은 1부터 세어 첫 행을 보지 못한다(§8).
 * @param
 * @returns
 * @hidden N
*/
scwin.openRsnPopup = async function () {
    const res = await $c.lc.popFindClssLstRsnCd(scwin.RSNCD_ADM_DESIGN, { mkt : "1", rsn : "07", spac : "N" });
    if (res?.isCloseButtonClick === true || $c.util.isEmpty(res?.code)) return;    // 취소·닫기

    const rows = dlt_rsn.getAllJSON();
    if (rows.some(row => row.admisuDesignRsnCd === res.code)) {
        await $c.win.alert("이미 선택하신 사유가 있습니다.");
        return;
    }

    const row = dlt_rsn.insertRow();
    dlt_rsn.setCellData(row, "admisuDesignRsnCd", res.code);
    dlt_rsn.setCellData(row, "admisuDesignRsnNm", res.name ?? "");
};

/**
 * @method
 * @name scwin.requestNext
 * @author Inswave
 * @date 2026. 10. 30
 * @description [해제]·[사유변경] — 다음에 열 화면과 그 data 를 반환하며 팝업을 닫는다. 부모(08031)가 목록을 재조회한 뒤 그 화면을 연다. (원본 fn_release·fn_rsnChange — 계약서 §3.2)
 *
 * 원본은 fn_GetPar 를 바꿔 끼우고 형제 팝업을 연 뒤 자기 창을 닫았다(CreateDialogFrame + CloseFrame).
 * 팝업 안에서 팝업을 열고 닫으면 자식 창의 수명이 끊기므로 부모 경유로 바꿨다.
 * selTp "0" 은 형제 팝업에서 왔다는 원본 표시(arr[7] "0")이고, 지정업무처리번호는 이 건의 번호다.
 * @param {String} id 다음 화면 ID (ULDSTF08033 해제 / ULDSTF08034 사유변경)
 * @param {String} tpCd 관리종목지정업무구분코드 (4 해제 / 1 사유변경)
 * @returns
 * @hidden N
*/
scwin.requestNext = async function (id, tpCd) {
    const data = {
        isurCd : scwin.isurCd,                  // 원본 arr[0] 발행기관코드
        isurNm : scwin.isurNm,                  // 원본 arr[1] 발행기관명
        secugrpId : scwin.secugrpId,            // 원본 arr[2] 증권그룹ID
        mktId : scwin.mktId,                    // 원본 arr[3] 시장구분코드
        bzProcsNo : "",                         // 원본 arr[4] 신규 작성 — 업무처리번호 없음
        admisuDesignBzTpCd : tpCd,              // 원본 arr[5]
        isuCd : dlt_isu.getCellData(0, "isuCd") || scwin.isuCd,     // 원본 arr[6] 종목코드
        selTp : "0",                            // 원본 arr[7] "0" — 형제 팝업에서 옴
        admisuDesignBzProcsNo : scwin.bzProcsNo // 원본 arr[8] 지정업무처리번호
    };

    await $c.win.closePopup({ isSaved : scwin.isSaved, next : { id : id, data : data } });
};

/**
 * @method
 * @name scwin.getDsclData
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성(ULDSTF92024)에 넘길 값. 원본 fn_dscl 이 fn_GetPar 로 채우던 arr[0..5] 와 데이터셋 3개(종목·마스터·사유)다. (§6.6)
 *
 * 마스터에는 원본처럼 고른 종목의 발행회사명(comNm)을 넣는다. 공시제목(arr[5])은 고른 종목의 종목명이다.
 * 원본은 arr[4] 를 비우고 arr[5] 를 넣어 길이 6 — 92024 는 본문을 생성하지 않는 서식으로 본다(원본 그대로).
 * @param
 * @returns {Object} 넘길 data
 * @hidden N
*/
scwin.getDsclData = function () {
    const focused = grd_isu.getFocusedRowIndex();
    const isu = dlt_isu.getRowJSON(focused < 0 ? 0 : focused) ?? {};

    return {
        formCd : scwin.DSCL_FORM_CD,                            // 원본 arr[0] "68344"
        bzProcsNo : scwin.bzProcsNo,                            // 원본 arr[1]
        isurCd : scwin.isurCd,                                  // 원본 arr[2]
        mktId : scwin.DSCL_MKT_ID,                              // 원본 arr[3] "1"
        msg : "",                                               // 원본 arr[4] 비움
        title : isu.isuNm ?? "",                                // 원본 arr[5] 종목명
        isu : dlt_isu.getAllJSON(),                             // 원본 CopyDataSet(dts_Isu)
        mst : [{ ...dma_mst.getJSON(), comNm : isu.comNm ?? "" }],  // 원본 CopyDataSet(dts_Mst) + COM_NM
        rsn : dlt_rsn.getAllJSON()                              // 원본 CopyDataSet(dts_Rsn)
    };
};

/**
 * @method
 * @name scwin.writeDscl
 * @author Inswave
 * @date 2026. 10. 30
 * @description 공시안내문작성. 공시안내문작성 팝업(ULDSTF92024)을 data 로 넘겨 열고 닫힐 때까지 기다린다. (원본 fn_dscl — §6.6)
 *
 * 원본은 닫힌 뒤 다시 조회하지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.writeDscl = async function () {
    const options = {
        id : "ULDSTF92024",
        popupName : "공시안내문작성",
        width : 745,
        height : 820,
        type : "pageFramePopup"
    };

    // TODO: 경로는 conversion-front 선례(/ui/listingcommon/), 92024 는 아직 getPar 계약이라 수신부 변경 필요 (§10)
    await $c.win.openPopup("/ui/listingcommon/ULDSTF92024.xml", options, scwin.getDsclData());
};

/**
 * @method
 * @name scwin.getPar
 * @author Inswave
 * @date 2026. 10. 30
 * @description [호환용 · 임시] 공시안내문작성(ULDSTF92024) 전환본은 아직 부모의 scwin.getPar 를 이름으로 불러 값을 받는다.
 * 92024 가 $c.data.getParameter() 수신으로 바뀌면 이 함수를 지운다. (§6.6, §10, 가이드 §6.5 예외)
 * @param {Array} arr 92024 가 넘기는 빈 배열 — [0] 서식코드 [1] 업무처리번호 [2] 발행기관코드 [3] 시장구분 [4] 비움 [5] 공시제목
 * @param {Object} dltIsu 92024 의 종목 dataList
 * @param {Object} dltMst 92024 의 마스터 dataList
 * @param {Object} dlt2 92024 의 원천 자료 2 (지정사유)
 * @returns {Number} arr 길이
 * @hidden N
*/
scwin.getPar = function (arr, dltIsu, dltMst, dlt2) {
    const data = scwin.getDsclData();

    arr[0] = data.formCd;
    arr[1] = data.bzProcsNo;
    arr[2] = data.isurCd;
    arr[3] = data.mktId;
    arr[4] = data.msg;
    arr[5] = data.title;

    scwin.fillDataList(dltIsu, data.isu);
    scwin.fillDataList(dltMst, data.mst);
    scwin.fillDataList(dlt2, data.rsn);

    return arr.length;
};

/**
 * @method
 * @name scwin.fillDataList
 * @author Inswave
 * @date 2026. 10. 30
 * @description 컬럼 정의가 비어 있는 92024 의 원천 dataList 에 행 키를 컬럼으로 더하고 행을 채운다. (원본 CopyDataSet 의 헤더 복사 — §6.6)
 * @param {Object} dataList 채울 dataList
 * @param {Array} rows 행 배열
 * @returns
 * @hidden N
*/
scwin.fillDataList = function (dataList, rows) {
    if (!dataList) return;

    Object.keys(rows[0] ?? {}).forEach(key => {
        if (dataList.getColumnIndex(key) < 0) dataList.insertColumn(key);
    });
    dataList.setJSON(rows);
};
